<?php require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../config/header.php'; if($_SESSION['user']['role']!=='admin'){http_response_code(403);die('Access denied');}
$day=$_GET['date']??date('Y-m-d');$s=$pdo->prepare("SELECT b.*,u.full_name FROM bills b JOIN users u ON u.id=b.cashier_id WHERE DATE(b.created_at)=? ORDER BY b.id DESC");$s->execute([$day]);$bills=$s->fetchAll();?><h2>Daily Sales: <?=e($day)?></h2><div class="actions no-print"><button onclick="window.print()">Print Report</button></div><div class="card"><table><tr><th>Bill</th><th>Customer</th><th>Cashier</th><th>Total</th><th>Status</th><th>Time</th></tr><?php foreach($bills as $b):?><tr><td><?=e($b['bill_no'])?></td><td><?=e($b['customer_name']?:'Walk-in')?></td><td><?=e($b['full_name'])?></td><td>TSh <?=number_format($b['total'])?></td><td><?=e($b['status'])?></td><td><?=e($b['created_at'])?></td></tr><?php endforeach;?></table></div><?php require_once __DIR__.'/../config/footer.php';?>
